const config = readConfig();
const pConfigured = await probe("configuredHealth");
const pApp = await probe("application");
const pReady = await probe("readiness");
const result = {
  config,
  probes: {
    configuredHealth: pConfigured,
    application: pApp,
    readiness: pReady
  },
  finding: pConfigured.status !== 200 && pApp.status === 200 ? "Configured health probe endpoint fails while application base and readiness respond successfully, indicating a probe path mismatch." : "Unexpected probe status combination."
};
console.log(JSON.stringify(result));
